// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;
    bytes32 constant IMPLEMENTATION_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
    bytes32 constant BEACON_SLOT = 0xa3f0ad74e5423aebfd80d3ef4346578335a9a72aeaee59ff6cb3582b35133d50;

    function setUp() public { c = new VaultAdapter(); }

    function testFuzz_property(uint256 seed) public {
        // Rule: from any caller context, c.proxiableUUID() reports the ERC1967
        // implementation slot, never any other slot (e.g. the beacon slot).
        vm.prank(address(uint160(bound(seed, 1, type(uint160).max))));
        bytes32 slot = c.proxiableUUID();
        assertTrue(slot == IMPLEMENTATION_SLOT && slot != BEACON_SLOT);
    }
}
